  const at = (d: string) => setClock(d);

  at(daysAgo(185));
  postJournal(ctx, { date: daysAgo(185), memo: "Owner capital introduced", source_type: "manual", lines: [{ account_id: account(ctx, "bank").id, debit: 2500000 }, { account_id: account(ctx, "cash").id, debit: 150000 }, { account_id: account(ctx, "equity").id, credit: 2650000 }] });

  const w1 = insert(db, "warehouses", { company_id: c1.id, business_id: b1.id, name: "Lahore Main Warehouse", code: "LHR-MAIN", location: "Kot Lakhpat Industrial Area, Lahore", manager_name: "Imran", status: "active" });
