  insert(db, "warehouses", { company_id: c2.id, business_id: b3.id, name: "Islamabad Godown", code: "ISB-01", location: "I-9 Industrial Area", status: "active" });
  insert(db, "warehouses", { company_id: c3.id, business_id: b4.id, name: "Main Store", code: "RWP-01", location: "Saddar", status: "active" });

  const P = (business: Row, wh: Row, name: string, sku: string, unit: string, cost: number, price: number, opening: number, min: number, category: string) =>
    createProduct(ctx, { name, sku, unit, cost_price: cost, selling_price: price, opening_stock: opening, min_stock_alert: min, warehouse_id: wh.id, category, barcode: `896${sku.replace(/\D/g, "").padStart(9, "0")}`, status: "active" }, business.id);

  const rice = P(b1, w1, "Basmati Rice 5kg", "RICE-5KG", "bag", 1850, 2350, 120, 30, "Grocery");
  const sugar = P(b1, w1, "Sugar 1kg", "SUG-1KG", "pcs", 140, 165, 400, 100, "Grocery");
  const oil = P(b1, w1, "Cooking Oil 5L", "OIL-5L", "ltr", 2450, 2850, 60, 25, "Grocery");
  const tea = P(b1, w1, "Black Tea 900g", "TEA-900", "pcs", 1150, 1420, 80, 20, "Beverages");
  const flour = P(b1, w1, "Wheat Flour 10kg", "FLR-10KG", "bag", 1150, 1380, 18, 25, "Grocery");
  const soap = P(b1, w2, "Beauty Soap 100g", "SOAP-100", "pcs", 95, 130, 300, 60, "Personal care");
  const shampoo = P(b1, w2, "Shampoo 400ml", "SHMP-400", "pcs", 520, 690, 8, 15, "Personal care");
  const water = P(b2, w3, "Mineral Water 1.5L (6 pack)", "WTR-6PK", "ctn", 420, 560, 150, 40, "Beverages");
  const biscuit = P(b2, w3, "Biscuits Family Pack", "BISC-FP", "box", 260, 340, 200, 50, "Snacks");
  const detergent = P(b2, w3, "Detergent Powder 1kg", "DET-1KG", "pcs", 380, 470, 12, 70, "Household");
  P(b2, w3, "Dish Wash Liquid 500ml", "DWL-500", "pcs", 230, 300, 90, 20, "Household");
  createProduct(ctx, { name: "Green Tea 25 bags (inactive)", sku: "GTEA-25", unit: "box", cost_price: 300, selling_price: 380, opening_stock: 0, min_stock_alert: 0, status: "inactive", category: "Beverages" }, b1.id);

  const S = (name: string, extra: Row = {}) => insert(db, "suppliers", { company_id: c1.id, business_id: null, name, email: null, phone: null, address: null, tax_number: null, contact_person: null, payment_terms_days: 30, opening_balance: 0, status: "active", notes: null, ...extra });
  const sup1 = S("Punjab Grain Mills", { email: "sales@punjabgrain.test", phone: "+92 42 111 222 333", address: "Sheikhupura Road, Lahore", contact_person: "Tariq Mehmood", tax_number: "NTN-7788990" });
  const sup2 = S("Sufi Edible Oils", { email: "orders@sufioils.test", phone: "+92 42 3500 1122", address: "Raiwind Road, Lahore", contact_person: "Nadia" });
  const sup3 = S("Clean Home Distributors", { email: "info@cleanhome.test", phone: "+92 21 3456 7890", address: "Korangi, Karachi", contact_person: "Asif" });
  const sup4 = S("Tea Gardens Pvt Ltd", { email: "trade@teagardens.test", phone: "+92 21 3111 4455", address: "Clifton, Karachi", contact_person: "Rehana", payment_terms_days: 15 });

  const C = (name: string, extra: Row = {}) => insert(db, "customers", { company_id: c1.id, business_id: null, name, email: null, phone: null, address: null, tax_number: null, contact_person: null, credit_limit: null, payment_terms_days: 15, status: "active", notes: null, contacts: [], ...extra });
  const cus1 = C("Hafeez Super Store", { email: "hafeez@store.test", phone: "+92 300 1112233", address: "Model Town, Lahore", contact_person: "Hafeez", credit_limit: 500000, contacts: [{ name: "Hafeez Ullah", role: "Owner", phone: "+92 300 1112233", email: "hafeez@store.test" }, { name: "Kamran", role: "Purchaser", phone: "+92 301 5556677", email: null }] });
  const cus2 = C("City Mart", { email: "buying@citymart.test", phone: "+92 42 3588 9900", address: "DHA Phase 5, Lahore", contact_person: "Saima", credit_limit: 800000, contacts: [{ name: "Saima Iqbal", role: "Buyer", phone: "+92 42 3588 9900", email: "buying@citymart.test" }] });
  const cus3 = C("Rehman General Store", { phone: "+92 321 4445566", address: "Johar Town, Lahore", contact_person: "Abdul Rehman" });
  const cus4 = C("Karachi Wholesale Hub", { email: "kwh@wholesale.test", phone: "+92 21 3222 1100", address: "Jodia Bazar, Karachi", contact_person: "Faisal", credit_limit: 300000 });
  const cus5 = C("Walk-in Customer", { notes: "Default cash customer" });

  const pm = (name: string) => db.tables.payment_methods.find((m) => m.company_id === c1.id && m.name === name)!;
  const cash = pm("Cash"), bankT = pm("Bank Transfer");

  /* historic sales over the last 6 months (delivered + paid) */
  const histProducts = [[rice, 2350], [sugar, 165], [oil, 2850], [tea, 1420], [soap, 130]] as const;
  const custs = [cus1, cus2, cus3, cus5];
  let k = 0;
  for (let m = 170; m >= 20; m -= 13) {
    at(daysAgo(m));
    const [p1, pr1] = histProducts[k % histProducts.length];
    const [p2, pr2] = histProducts[(k + 2) % histProducts.length];
    const cust = custs[k % custs.length];
    const sale = saveSale(ctx, { customer_id: cust.id, sale_date: daysAgo(m), warehouse_id: p1.id === soap.id ? w2.id : w1.id, items: [{ product_id: p1.id, quantity: 4 + (k % 5), unit_price: pr1, discount: k % 3 === 0 ? 2 : 0, tax_rate: 0 }, { product_id: p2.id, quantity: 6 + (k % 4), unit_price: pr2, tax_rate: 0 }] }, b1.id);
    // keep each historic sale single-warehouse: soap lives in the store room
    if (sale.items.some((l: Row) => l.product_id === soap.id) && sale.items.some((l: Row) => l.product_id !== soap.id)) {
      sale.items = sale.items.filter((l: Row) => l.product_id !== soap.id);
      sale.subtotal = sale.items.reduce((s: number, l: Row) => s + l.line_subtotal, 0);
      sale.discount_amount = sale.items.reduce((s: number, l: Row) => s + l.discount_amount, 0);
      sale.tax_amount = sale.items.reduce((s: number, l: Row) => s + l.tax_amount, 0);
      sale.total_amount = sale.items.reduce((s: number, l: Row) => s + l.total, 0);
      sale.warehouse_id = w1.id;
    }
    const out = confirmSale(ctx, sale);
    dispatchOutward(ctx, out);
    at(daysAgo(m - 1));
    deliverOutward(ctx, out);
    at(daysAgo(m - 5));
    createPayment(ctx, { direction: "in", party_id: cust.id, amount: sale.total_amount, payment_method_id: k % 2 ? bankT.id : cash.id, reference: k % 2 ? `IBFT-${7000 + k}` : null, payment_date: daysAgo(m - 5), allocations: [{ document_id: sale.id, amount: sale.total_amount }] });
    k++;
  }

  /* purchases */
  at(daysAgo(60));
  const po1 = savePurchase(ctx, { supplier_id: sup1.id, purchase_date: daysAgo(60), warehouse_id: w1.id, reference: "PG-INV-5512", items: [{ product_id: rice.id, quantity: 100, unit_price: 1800, tax_rate: 0 }, { product_id: flour.id, quantity: 60, unit_price: 1120, discount: 2 }] }, b1.id);
  const in1 = confirmPurchase(ctx, po1);
  at(daysAgo(58));
  tallyInward(ctx, in1, { items: [{ product_id: rice.id, received_quantity: 100 }, { product_id: flour.id, received_quantity: 60 }] });
  at(daysAgo(40));
  createPayment(ctx, { direction: "out", party_id: sup1.id, amount: 150000, payment_method_id: bankT.id, reference: "CHQ-00451", payment_date: daysAgo(40), allocations: [{ document_id: po1.id, amount: 150000 }] });
