  const po2 = savePurchase(ctx, { supplier_id: sup2.id, purchase_date: daysAgo(45), warehouse_id: w1.id, items: [{ product_id: oil.id, quantity: 40, unit_price: 2400, tax_rate: 17 }] }, b1.id);
  const in2 = confirmPurchase(ctx, po2);
  at(daysAgo(44));
  tallyInward(ctx, in2, { items: [{ product_id: oil.id, received_quantity: 40 }] });
  at(daysAgo(30));
  createPayment(ctx, { direction: "out", party_id: sup2.id, amount: po2.billed_amount, payment_method_id: bankT.id, reference: "IBFT-88120", payment_date: daysAgo(30), allocations: [{ document_id: po2.id, amount: po2.billed_amount }] });

  at(daysAgo(12));
  const po3 = savePurchase(ctx, { supplier_id: sup4.id, purchase_date: daysAgo(12), warehouse_id: w1.id, items: [{ product_id: tea.id, quantity: 60, unit_price: 1100, tax_rate: 17 }, { product_id: sugar.id, quantity: 300, unit_price: 138 }] }, b1.id);
  const in3 = confirmPurchase(ctx, po3);
  at(daysAgo(10));
  tallyInward(ctx, in3, { items: [{ product_id: tea.id, received_quantity: 35 }, { product_id: sugar.id, received_quantity: 300 }] });

  at(daysAgo(4));
  const po4 = savePurchase(ctx, { supplier_id: sup1.id, purchase_date: daysAgo(4), expected_date: daysAgo(-3), warehouse_id: w1.id, items: [{ product_id: flour.id, quantity: 80, unit_price: 1130 }] }, b1.id);
